// Author: Aldrin Payopay <aldrin.gdf@gmail.com>
declare name "Soft Drive";
declare author "Aldrin Payopay";
import("stdfaust.lib");
cutoff = hslider("cutoff[unit:Hz][scale:log]",5000,80,18000,1) : si.smoo;
drive = hslider("drive[unit:dB]",6,0,24,0.1) : ba.db2linear : si.smoo;
mix = hslider("mix",0.65,0,1,0.01) : si.smoo;
level = hslider("level[unit:dB]",-6,-36,0,0.1) : ba.db2linear : si.smoo;
// Keep filter coefficients inside the stable frequency range at every supported rate.
color(x) = x*(1-mix)+ma.tanh(fi.lowpass(2,min(cutoff,ma.SR*0.45),x)*drive)*mix;
process = par(i,2,color : *(level));

