			output0[i0] = (FAUSTFLOAT)(dsp->fRec0[0] * ((fTemp0 * fTemp1) + (dsp->fRec1[0] * tanhf((dsp->fRec2[0] * (dsp->fRec3[2] + (dsp->fRec3[0] + (2.0f * dsp->fRec3[1])))) / fTemp6))));
			float fTemp7 = (float)(input1[i0]);
			dsp->fRec5[0] = fTemp7 - (((fTemp4 * dsp->fRec5[2]) + (2.0f * (fTemp5 * dsp->fRec5[1]))) / fTemp6);
			output1[i0] = (FAUSTFLOAT)(dsp->fRec0[0] * ((fTemp7 * fTemp1) + (dsp->fRec1[0] * tanhf((dsp->fRec2[0] * (dsp->fRec5[2] + (dsp->fRec5[0] + (2.0f * dsp->fRec5[1])))) / fTemp6))));
