    return index < DSP_PARAMETER_COUNT ? &dsp_parameters[index] : NULL;
}
int dsp_soft_drive_set(void *context, size_t index, float value) {
    if (!context || index >= DSP_PARAMETER_COUNT || !isfinite(value)) return 0;
    const DspParameter *p = &dsp_parameters[index];
    if (value < p->minimum || value > p->maximum) return 0;
    DspSoftDrive *dsp = (DspSoftDrive *)context;
    switch (index) { case 0: dsp->fHslider3=value; break;
case 1: dsp->fHslider2=value; break;
case 2: dsp->fHslider0=value; break;
case 3: dsp->fHslider1=value; break; default: return 0; }
