static double card_clock(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}
int main(int argc, char **argv) {
    if (argc != 8) {
        fprintf(stderr,"usage: render rate frames block input.f32 output.f32 params.txt events.txt\n"); return 2;
    }
    char *end;
    long rate=strtol(argv[1],&end,10); if (*end || rate<8000 || rate>192000) return 2;
    long frames=strtol(argv[2],&end,10); if (*end || frames<1 || frames>rate*90) return 2;
    long block=strtol(argv[3],&end,10); if (*end || block<1 || block>8192) return 2;
    DspSoftDrive *dsp=dsp_soft_drive_create((int)rate); if (!dsp) return 3;
    float *in[2]={NULL,NULL}, *out[2]={NULL,NULL};
    for(int c=0;c<DSP_INPUT_COUNT;c++) in[c]=calloc((size_t)block,sizeof(float));
    for(int c=0;c<DSP_OUTPUT_COUNT;c++) out[c]=calloc((size_t)block,sizeof(float));
