    float *result=calloc((size_t)frames*DSP_OUTPUT_COUNT,sizeof(float));
    if(!source||!result) return 3;
    for(int c=0;c<DSP_INPUT_COUNT;c++) if(!in[c]) return 3;
    for(int c=0;c<DSP_OUTPUT_COUNT;c++) if(!out[c]) return 3;
