    while((fields=fscanf(params,"%zu %f",&parameter,&value))==2) if(!dsp_soft_drive_set(dsp,parameter,value)) return 4;
    if(fields!=EOF) return 4;
    fclose(params);
    long event_frame=0; size_t event_param=0; float event_value=0;
    fields=fscanf(events,"%ld %zu %f",&event_frame,&event_param,&event_value);
    if(fields!=3&&fields!=EOF) return 4;
    int has_event=fields==3;
    double sum=0, maximum=0; long calls=0; double peak=0;
    for(long at=0;at<frames;) {
        while(has_event && event_frame==at) {
            if(!dsp_soft_drive_set(dsp,event_param,event_value)) return 4;
            fields=fscanf(events,"%ld %zu %f",&event_frame,&event_param,&event_value);
            if(fields!=3&&fields!=EOF) return 4;
            has_event=fields==3;
        }
